const burger = document.querySelector('.burger');
const close_btn = document.querySelector('.close_btn');
const mobile_menu = document.querySelector('.mobile_menu');
const body = document.querySelector('body');
const overlay = document.querySelector('.overlay');

burger.addEventListener("click", function () {
    mobile_menu.classList.toggle("show");
    overlay.style = 'display:block'
});

close_btn.addEventListener("click", function () {
    mobile_menu.classList.toggle("show");
    overlay.style = 'display:none'
});

const showFaq = (event) => {
    const accordion__lists = event.querySelector('.accordion__lists')
    const minus = event.querySelector('.minus')
    accordion__lists.classList.toggle("show");
    minus.classList.toggle("minus_none");
}

const showMinus = () => {
    const plus = document.querySelector('#plus')
    plus.classList.toggle("show");

    const minus = document.querySelector('#minus')
    minus.classList.remove("show");
}

const showPlus = () => {
    const plus = document.querySelector('#plus')
    plus.classList.toggle("show");

    const minus = document.querySelector('#minus')
    minus.classList.remove("show");
}
